  try {
    if (!req.query.viewer) return res.status(400).send('Missing parameter');
    const name = escapeHtml(req.query.viewer || 'guest');
    const room = escapeHtml(req.query.stream || 'general');
    metrics.track('stream_ping', { room });
    res.send(`<h2>${name} joined ${room}</h2>`);
  } catch (err) {
    res.status(500).send('Something went wrong');
  }
});

